export function Breadcrumbs({
  items,
}: {
  items: { label: string; href?: string }[];
}) {
  return (
    <nav aria-label="Breadcrumb">
      <ol className="flex items-center gap-2 text-sm">
        {items.map((item, i) => (
          <li key={item.label} className="flex items-center gap-2">
            {item.href ? (
              <a
                href={item.href}
                className="group relative text-slate-500 transition-colors hover:text-slate-900 dark:text-slate-400 dark:hover:text-white"
              >
                {item.label}
                <span className="absolute inset-x-0 -bottom-0.5 h-px origin-left scale-x-0 bg-slate-900 transition-transform duration-300 ease-out group-hover:scale-x-100 dark:bg-white" />
              </a>
            ) : (
              <span aria-current="page" className="font-medium text-slate-900 dark:text-white">
                {item.label}
              </span>
            )}
            {i < items.length - 1 && <span className="text-slate-300 dark:text-slate-600">/</span>}
          </li>
        ))}
      </ol>
    </nav>
  );
}
